+)
+
+func TestApplyValueTraitsRejectsNestedUnsupportedInternalTrait(t *testing.T) {
+	_, err := ApplyValueTraits(`{{regexp.replace(email.local(internal.secret), "^a$", "b")}}`, map[string][]string{"secret": {"a@example.com"}})
